from AlgorithmImports import *
from collections import deque


class StrategySystemAlgorithm(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)
        self.Settings.DailyPreciseEndTime = True

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.rsi_value = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        self._synchronize_lots()

        bars = {
            symbol: data.Bars[symbol]
            for symbol in self.symbols
            if data.Bars.ContainsKey(symbol)
        }

        spy_crossed_above = False
        spy_crossed_below = False

        if self.spy in bars:
            spy_crossed_above, spy_crossed_below = self._update_spy(
                float(bars[self.spy].Close)
            )

        if self.aapl in bars:
            self._update_aapl(float(bars[self.aapl].Close))

        if len(bars) != len(self.symbols):
            return

        if self.spy_previous_sma is None or self.rsi_value is None:
            return

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)
        available_cash = float(self.Portfolio.Cash)

        if self.spy_lot > 0 and spy_crossed_below:
            quantity = self.spy_lot
            self.MarketOrder(
                self.spy, -quantity, False, "Strategy A: close crossed below SMA"
            )
            self.spy_lot = 0
            available_cash += quantity * spy_close

        if self.aapl_lot > 0 and self.rsi_value > 60:
            quantity = self.aapl_lot
            self.MarketOrder(
                self.aapl, -quantity, False, "Strategy B: RSI closed above 60"
            )
            self.aapl_lot = 0
            available_cash += quantity * aapl_close

        if self.spy_lot == 0 and spy_crossed_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(target_value / spy_close)
            if quantity > 0:
                self.MarketOrder(
                    self.spy, quantity, False, "Strategy A: close crossed above SMA"
                )
                self.spy_lot = quantity
                available_cash -= quantity * spy_close

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if available_cash >= 20_000:
                quantity = int(20_000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        False,
                        "Strategy B: red for at least 3 consecutive days",
                    )
                    self.aapl_lot = quantity

    def _update_spy(self, close):
        self.spy_closes.append(close)
        current_sma = None

        if len(self.spy_closes) == self.SMA_PERIOD:
            current_sma = sum(self.spy_closes) / self.SMA_PERIOD

        crossed_above = False
        crossed_below = False

        if (
            current_sma is not None
            and self.spy_previous_close is not None
            and self.spy_previous_sma is not None
        ):
            crossed_above = (
                self.spy_previous_close <= self.spy_previous_sma
                and close > current_sma
            )
            crossed_below = (
                self.spy_previous_close >= self.spy_previous_sma
                and close < current_sma
            )

        self.spy_previous_close = close
        self.spy_previous_sma = current_sma
        return crossed_above, crossed_below

    def _update_aapl(self, close):
        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            change = close - self.aapl_previous_close
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.rsi_average_gain is None:
                self.rsi_seed_gains.append(gain)
                self.rsi_seed_losses.append(loss)

                if len(self.rsi_seed_gains) == self.RSI_PERIOD:
                    self.rsi_average_gain = (
                        sum(self.rsi_seed_gains) / self.RSI_PERIOD
                    )
                    self.rsi_average_loss = (
                        sum(self.rsi_seed_losses) / self.RSI_PERIOD
                    )
                    self._set_rsi_value()
            else:
                self.rsi_average_gain = (
                    self.rsi_average_gain * (self.RSI_PERIOD - 1) + gain
                ) / self.RSI_PERIOD
                self.rsi_average_loss = (
                    self.rsi_average_loss * (self.RSI_PERIOD - 1) + loss
                ) / self.RSI_PERIOD
                self._set_rsi_value()

        self.aapl_previous_close = close

    def _set_rsi_value(self):
        if self.rsi_average_loss == 0:
            self.rsi_value = 100.0
        else:
            relative_strength = self.rsi_average_gain / self.rsi_average_loss
            self.rsi_value = 100.0 - (100.0 / (1.0 + relative_strength))

    def _synchronize_lots(self):
        if not self.Transactions.GetOpenOrders(self.spy):
            self.spy_lot = max(0, int(self.Portfolio[self.spy].Quantity))

        if not self.Transactions.GetOpenOrders(self.aapl):
            self.aapl_lot = max(0, int(self.Portfolio[self.aapl].Quantity))

