from decimal import Decimal


class ParallelStrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)
        self.Settings.DailyPreciseEndTime = True

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(20)
        self.spy_close_sma_history = deque(maxlen=2)

        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.WILDERS
        )
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

            if self.spy_sma.IsReady:
                self.spy_close_sma_history.append(
                    (spy_bar.Close, self.spy_sma.Current.Value)
                )

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]

            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_bar.Close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if any(
            not data.Bars.ContainsKey(symbol)
            for symbol in self.symbols.values()
        ):
            return

        if (
            len(self.spy_close_sma_history) < 2
            or not self.aapl_rsi.IsReady
        ):
            return

        yesterday_close, yesterday_sma = self.spy_close_sma_history[0]
        today_close, today_sma = self.spy_close_sma_history[1]

        spy_crossed_above = (
            yesterday_close <= yesterday_sma
            and today_close > today_sma
        )
        spy_crossed_below = (
            yesterday_close >= yesterday_sma
            and today_close < today_sma
        )

        spy_quantity = self.Portfolio[self.spy].Quantity
        aapl_quantity = self.Portfolio[self.aapl].Quantity

        spy_has_open_orders = (
            len(self.Transactions.GetOpenOrders(self.spy)) > 0
        )
        aapl_has_open_orders = (
            len(self.Transactions.GetOpenOrders(self.aapl)) > 0
        )

        if (
            spy_quantity > 0
            and not spy_has_open_orders
            and spy_crossed_below
        ):
            self.MarketOrder(
                self.spy,
                -spy_quantity,
                tag="Strategy A: close crossed below SMA"
            )

